union TSetupLoadCounterAlias {
    TAbstractFile** fileSlot;
    int* counterSlot;
};

static __forceinline int& setup_load_counter_slot(TAbstractFile*& fileSlot)
{
    TSetupLoadCounterAlias alias;
    alias.fileSlot = &fileSlot;
    return *alias.counterSlot;
}

