                case TREASURE_CHEST:
                    RandomizeTreasure(tempCell);
                    break;

                case TREE_OF_KNOWLEDGE:
                    tempCell->extraInfo =
                        (tempCell->extraInfo & 0xffffe000)
                        | (numTreeOfKnowledge++ & 0x1f);
                    id = Random(0, 2);
                    tempCell->extraInfo =
                        (tempCell->extraInfo & 0xffff1fff)
                        | ((id & 7) << 13);
