                    if (tempCell->type == RANDOM_TOWN) {
                        tempCell->type = TOWN;
                        tempCell->objectIndex = townExtra->townType;
                        ConvertObject(tempCell);
                    }

                    if (townExtra->bCustomName)
                        currTown->cName = townExtra->name;
                    else
                        currTown->cName.assign(
                            GetRandomTownName(townExtra->townType));

